INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Strange Happenings in My Town', 'Last week, some strange things happened in my small town. Every night, people heard strange noises outside. "What could it be?" everyone asked. My neighbor Victor said it might be a dog. But I didn''t agree. A dog can''t make such a loud noise. My mother thought it could be the wind. But the wind can''t move things around. One morning, we found rubbish all over the street. It must be an animal looking for food, but which animal? Finally, a policeman found the answer. It was a group of large birds! They came at night to look for food. The mystery was solved at last.', '记叙文', 106, '[{"q": "When did the strange things happen?", "answer": "A", "options": ["Last week.", "Yesterday.", "Last month.", "Last year."], "explanation": "原文:Last week"}, {"q": "What did people hear every night?", "answer": "C", "options": ["Voices.", "Strange lights.", "Strange noises.", "Music."], "explanation": "原文:heard strange noises"}, {"q": "What did Victor think it might be?", "answer": "D", "options": ["A bird.", "A wolf.", "The wind.", "A dog."], "explanation": "原文:Victor said it might be a dog"}, {"q": "What did they find one morning?", "answer": "C", "options": ["A dog.", "A note.", "Rubbish all over the street.", "Footprints."], "explanation": "原文:rubbish all over the street"}, {"q": "What was the cause of the noise?", "answer": "B", "options": ["A wolf.", "Large birds looking for food.", "A dog.", "The wind."], "explanation": "原文:a group of large birds"}]'::jsonb, '[{"word": "noise", "cn": "噪音"}, {"word": "rubbish", "cn": "垃圾"}, {"word": "mystery", "cn": "奥秘;神秘事物"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The Mystery of Stonehenge', 'Stonehenge is one of the most famous mysteries in the world. It is a circle of large stones in Britain. The stones are very old and very heavy. No one knows for sure why Stonehenge was built. Some people think it might have been a place for medical care. Others believe it could have been a temple where people honored their ancestors. Some historians say it must have been used to watch the sun and stars. The biggest mystery is how the stones were moved. They weigh thousands of kilos, and there were no trucks long ago. Stonehenge still keeps its secrets today.', '说明文', 103, '[{"q": "Where is Stonehenge?", "answer": "A", "options": ["In Britain.", "In the US.", "In China.", "In France."], "explanation": "原文:in Britain"}, {"q": "What is Stonehenge made of?", "answer": "D", "options": ["Wood.", "Metal.", "Glass.", "Large stones."], "explanation": "原文:a circle of large stones"}, {"q": "What might Stonehenge have been used for?", "answer": "A", "options": ["Medical care or a temple.", "A house.", "A school.", "A shop."], "explanation": "原文:medical care...temple"}, {"q": "What do some historians think it was used to watch?", "answer": "C", "options": ["Animals.", "The sea.", "The sun and stars.", "People."], "explanation": "原文:watch the sun and stars"}, {"q": "What is the biggest mystery?", "answer": "B", "options": ["Why it''s famous.", "How the stones were moved.", "When it rains.", "Who lived there."], "explanation": "原文:how the stones were moved"}]'::jsonb, '[{"word": "mystery", "cn": "奥秘"}, {"word": "temple", "cn": "庙宇;圣殿"}, {"word": "historian", "cn": "历史学家"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'The UFO Night', 'One summer night, Jean saw something strange in the sky. A bright light was moving slowly above her house. "It can''t be a plane," she thought. "It moves too strangely." The light landed in a field nearby. Jean felt uneasy. She wanted to know what it was. Could it be a UFO? Could there be aliens inside? She told her friends the next day. Some said it might be a weather balloon. Others said it must be a trick of the light. Jean was not sure. To this day, she still wonders what she really saw that night. Some mysteries may never be solved.', '记叙文', 104, '[{"q": "When did Jean see something strange?", "answer": "C", "options": ["One winter day.", "One morning.", "One summer night.", "Last week."], "explanation": "原文:One summer night"}, {"q": "What was moving in the sky?", "answer": "D", "options": ["A bird.", "A plane.", "A cloud.", "A bright light."], "explanation": "原文:A bright light was moving"}, {"q": "Why did Jean think it wasn''t a plane?", "answer": "B", "options": ["It was too quiet.", "It moved too strangely.", "It was too fast.", "It was too small."], "explanation": "原文:moves too strangely"}, {"q": "Where did the light land?", "answer": "C", "options": ["On her house.", "On the road.", "In a field nearby.", "In the sea."], "explanation": "原文:landed in a field"}, {"q": "How did Jean feel?", "answer": "A", "options": ["Uneasy.", "Bored.", "Happy.", "Sleepy."], "explanation": "原文:Jean felt uneasy"}]'::jsonb, '[{"word": "uneasy", "cn": "不安的"}, {"word": "land", "cn": "着陆;降落"}, {"word": "alien", "cn": "外星人"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Whose Things Are These?', 'After the school party, the teacher found many things left behind. "Whose are these?" she asked. There was a blue coat. It must belong to a boy, because it was big. There was also a pink hair band. It might belong to a girl with long hair. A science book was on the desk. It could be Tom''s, because he loves science. There was also a volleyball. It must be Carla''s, because she plays volleyball every day. The teacher put all the things in the lost-and-found box. She hoped the students would come and take their things back soon.', '记叙文', 99, '[{"q": "When did the teacher find the things?", "answer": "B", "options": ["At night.", "After the school party.", "During lunch.", "Before class."], "explanation": "原文:After the school party"}, {"q": "Who must the blue coat belong to?", "answer": "A", "options": ["A boy.", "Tom.", "A girl.", "The teacher."], "explanation": "原文:must belong to a boy"}, {"q": "Who might the pink hair band belong to?", "answer": "B", "options": ["The teacher.", "A girl with long hair.", "Carla''s brother.", "A boy."], "explanation": "原文:a girl with long hair"}, {"q": "Why could the science book be Tom''s?", "answer": "A", "options": ["He loves science.", "He sits there.", "He is new.", "He is tall."], "explanation": "原文:he loves science"}, {"q": "Who must the volleyball belong to?", "answer": "C", "options": ["Tom.", "Victor.", "Carla.", "Jean."], "explanation": "原文:must be Carla''s"}]'::jsonb, '[{"word": "coat", "cn": "外套"}, {"word": "pink", "cn": "粉红色的"}, {"word": "belong", "cn": "属于"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Making Guesses', 'In daily life, we often make guesses about things we are not sure of. We use special words to show how sure we are. If we are very sure, we use "must". For example, if the lights are on, someone must be home. If we are less sure, we use "might" or "could". The keys might be in the kitchen, or they could be in the car. If we think something is impossible, we use "can''t". A small cat can''t make such a loud sound. Making guesses is a useful skill. It helps us understand the world around us. But we should remember that a guess is not always right.', '议论文', 110, '[{"q": "What do we often make about uncertain things?", "answer": "B", "options": ["Rules.", "Guesses.", "Plans.", "Lists."], "explanation": "原文:make guesses"}, {"q": "Which word shows we are very sure?", "answer": "D", "options": ["Can''t.", "Might.", "Could.", "Must."], "explanation": "原文:very sure, we use must"}, {"q": "Which words show we are less sure?", "answer": "D", "options": ["Must.", "Can''t.", "Should.", "Might or could."], "explanation": "原文:less sure...might or could"}, {"q": "Which word shows something is impossible?", "answer": "A", "options": ["Can''t.", "Might.", "Could.", "Must."], "explanation": "原文:impossible, we use can''t"}, {"q": "What should we remember about a guess?", "answer": "C", "options": ["It is always right.", "It is easy.", "It is not always right.", "It is useless."], "explanation": "原文:not always right"}]'::jsonb, '[{"word": "guess", "cn": "猜测"}, {"word": "sure", "cn": "确信的"}, {"word": "impossible", "cn": "不可能的"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Lost and Found Notice', 'SCHOOL LOST AND FOUND. The following things were found last week. Please come to Room 105 to collect them. A PAIR OF GLASSES: Found in the library. They must belong to someone who reads a lot. A SCHOOL BAG: Found in the gym. There is a basketball inside, so it might belong to a player. A WATCH: Found near the science lab. It looks valuable, so please come quickly. A SET OF KEYS: Found in the playground. They could belong to anyone, so check if yours are missing. To collect your things, you must show your student card. Office hours: 8:00 a.m. to 5:00 p.m.', '应用文', 105, '[{"q": "Where can students collect lost things?", "answer": "C", "options": ["The library.", "The playground.", "Room 105.", "The gym."], "explanation": "原文:come to Room 105"}, {"q": "Where were the glasses found?", "answer": "D", "options": ["Near the lab.", "In the gym.", "In the playground.", "In the library."], "explanation": "原文:Found in the library"}, {"q": "Why might the school bag belong to a player?", "answer": "D", "options": ["It is big.", "It is blue.", "It is new.", "There is a basketball inside."], "explanation": "原文:a basketball inside"}, {"q": "What must students show to collect things?", "answer": "A", "options": ["Their student card.", "A letter.", "Money.", "A photo."], "explanation": "原文:must show your student card"}, {"q": "When does the office close?", "answer": "B", "options": ["6:00 p.m.", "5:00 p.m.", "8:00 a.m.", "12:00 p.m."], "explanation": "原文:to 5:00 p.m."}]'::jsonb, '[{"word": "valuable", "cn": "贵重的"}, {"word": "library", "cn": "图书馆"}, {"word": "collect", "cn": "收集;领取"}]'::jsonb, 3, '9', 'U8');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'The Noise at Night', 'One night, my family heard a strange (1)____ outside. "What (2)____ it be?" my father asked. I thought it (3)____ be a cat, but I wasn''t sure. My mother said it (4)____ be the wind, but the wind can''t move things. "It (5)____ be a big animal," said my brother. "It''s too loud to be a small one." We felt a little (6)____. The next morning, we found our rubbish bins were open. There (7)____ have been an animal looking for (8)____. Finally, my father saw it: a large dog from next door! The (9)____ was solved. We all (10)____ when we knew the truth.', 105, 3, '[{"q": "1", "answer": "A", "options": ["noise", "game", "price", "color"], "explanation": "噪音 noise"}, {"q": "2", "answer": "A", "options": ["could", "must", "mustn''t", "can''t"], "explanation": "could it be 可能"}, {"q": "3", "answer": "B", "options": ["mustn''t", "might", "can''t", "must"], "explanation": "might be 可能"}, {"q": "4", "answer": "D", "options": ["can''t", "must", "mustn''t", "might"], "explanation": "might be 可能"}, {"q": "5", "answer": "C", "options": ["can''t", "might", "must", "could"], "explanation": "must be 一定"}, {"q": "6", "answer": "D", "options": ["proud", "happy", "sleepy", "uneasy"], "explanation": "不安 uneasy"}, {"q": "7", "answer": "B", "options": ["could", "must", "might", "can''t"], "explanation": "must have been 一定"}, {"q": "8", "answer": "C", "options": ["books", "color", "food", "music"], "explanation": "找食物 food"}, {"q": "9", "answer": "A", "options": ["mystery", "color", "game", "price"], "explanation": "谜团 mystery"}, {"q": "10", "answer": "B", "options": ["ran", "laughed", "slept", "cried"], "explanation": "笑了 laughed"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'Whose Bag Is This?', 'After class, I found a school bag on the (1)____. "Whose bag is this?" I wondered. It (2)____ belong to a boy, because it was big and blue. I opened it to look for a (3)____. Inside, there was a basketball, so it (4)____ belong to someone who plays sports. There was also a science (5)____. The owner (6)____ love science. Then I saw a name on the book: "Tom". So the bag (7)____ be Tom''s! I was happy to find the (8)____. I took the bag to Tom. He was very (9)____ to get it back. "Thank you so much," he said. Helping others always makes me (10)____.', 109, 3, '[{"q": "1", "answer": "C", "options": ["game", "color", "desk", "price"], "explanation": "桌上 desk"}, {"q": "2", "answer": "B", "options": ["can''t", "must", "could", "might"], "explanation": "must belong 一定"}, {"q": "3", "answer": "A", "options": ["name", "price", "song", "color"], "explanation": "名字 name"}, {"q": "4", "answer": "D", "options": ["could", "can''t", "might", "must"], "explanation": "must belong 一定"}, {"q": "5", "answer": "C", "options": ["price", "color", "book", "game"], "explanation": "书 book"}, {"q": "6", "answer": "A", "options": ["must", "can''t", "could", "might"], "explanation": "must love 一定"}, {"q": "7", "answer": "B", "options": ["might", "must", "could", "can''t"], "explanation": "must be 一定"}, {"q": "8", "answer": "D", "options": ["game", "price", "color", "owner"], "explanation": "主人 owner"}, {"q": "9", "answer": "B", "options": ["sad", "happy", "tired", "angry"], "explanation": "开心 happy"}, {"q": "10", "answer": "A", "options": ["happy", "sad", "angry", "bored"], "explanation": "开心 happy"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'The Old Castle', 'Last summer, my family visited an old (1)____ in the countryside. It was very old and full of (2)____. "Who (3)____ have lived here?" I asked. The guide said it (4)____ have been the home of a king long ago. Some rooms were very large. They (5)____ have been used for big parties. One small room (6)____ have been a prison, because it had thick walls and no windows. We weren''t (7)____, of course, but it was fun to (8)____. The castle (9)____ keeps its secrets, but visiting it was a wonderful (10)____. I hope to go there again someday.', 100, 3, '[{"q": "1", "answer": "B", "options": ["color", "castle", "price", "game"], "explanation": "城堡 castle"}, {"q": "2", "answer": "A", "options": ["mystery", "color", "price", "song"], "explanation": "神秘 mystery"}, {"q": "3", "answer": "C", "options": ["mustn''t", "must", "could", "can''t"], "explanation": "could have lived 可能"}, {"q": "4", "answer": "D", "options": ["can''t", "must", "mustn''t", "might"], "explanation": "might have been 可能"}, {"q": "5", "answer": "A", "options": ["could", "mustn''t", "can''t", "must"], "explanation": "could have been 可能"}, {"q": "6", "answer": "A", "options": ["might", "mustn''t", "must", "can''t"], "explanation": "might have been 可能"}, {"q": "7", "answer": "B", "options": ["sleepy", "sure", "happy", "tired"], "explanation": "确定 sure"}, {"q": "8", "answer": "C", "options": ["break", "lose", "guess", "throw"], "explanation": "猜 guess"}, {"q": "9", "answer": "D", "options": ["seldom", "once", "never", "still"], "explanation": "仍然 still"}, {"q": "10", "answer": "B", "options": ["color", "experience", "price", "game"], "explanation": "经历 experience"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'A Surprise Gift', 'One day, I found a small box on my (1)____. There was no name on it. "Whose (2)____ this be?" I wondered. It (3)____ be for me, but I wasn''t sure. I opened it carefully. Inside was a (4)____ watch. It looked very (5)____. "Who (6)____ have left this?" I thought. It (7)____ be from my parents, because my birthday was coming. Or it (8)____ be from a friend. Later, my mother told me the (9)____. The watch was a birthday gift from my grandmother! I was so (10)____. I called her at once to say thank you.', 98, 3, '[{"q": "1", "answer": "A", "options": ["desk", "price", "color", "game"], "explanation": "桌上 desk"}, {"q": "2", "answer": "D", "options": ["must", "mustn''t", "can''t", "could"], "explanation": "could this be 可能"}, {"q": "3", "answer": "B", "options": ["must", "might", "mustn''t", "can''t"], "explanation": "might be 可能"}, {"q": "4", "answer": "C", "options": ["bad", "sour", "nice", "cold"], "explanation": "漂亮 nice"}, {"q": "5", "answer": "D", "options": ["cheap", "broken", "old", "valuable"], "explanation": "贵重 valuable"}, {"q": "6", "answer": "A", "options": ["could", "must", "mustn''t", "can''t"], "explanation": "could have left 可能"}, {"q": "7", "answer": "C", "options": ["can''t", "mustn''t", "might", "must"], "explanation": "might be 可能"}, {"q": "8", "answer": "A", "options": ["could", "can''t", "mustn''t", "must"], "explanation": "could be 可能"}, {"q": "9", "answer": "B", "options": ["color", "truth", "price", "game"], "explanation": "真相 truth"}, {"q": "10", "answer": "B", "options": ["angry", "happy", "sad", "tired"], "explanation": "开心 happy"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'The Strange Light', 'Late one night, Tom saw a strange (1)____ in the sky. It was moving slowly. "It (2)____ be a plane," he thought, "because planes don''t move like that." The light was very (3)____. "It (4)____ be a UFO," he wondered, but he wasn''t sure. He felt a bit (5)____ and called his friend. His friend said it (6)____ be a weather balloon. "Or it (7)____ be a trick of the light," he added. Tom looked again, but the light was (8)____. To this day, Tom doesn''t know what he (9)____. Some mysteries may never be (10)____. But it was an exciting night for him.', 104, 3, '[{"q": "1", "answer": "C", "options": ["price", "color", "light", "game"], "explanation": "光 light"}, {"q": "2", "answer": "D", "options": ["could", "must", "might", "can''t"], "explanation": "can''t be 不可能"}, {"q": "3", "answer": "A", "options": ["bright", "cold", "sour", "dark"], "explanation": "明亮 bright"}, {"q": "4", "answer": "C", "options": ["mustn''t", "can''t", "might", "must"], "explanation": "might be 可能"}, {"q": "5", "answer": "A", "options": ["uneasy", "happy", "sleepy", "proud"], "explanation": "不安 uneasy"}, {"q": "6", "answer": "B", "options": ["mustn''t", "could", "must", "can''t"], "explanation": "could be 可能"}, {"q": "7", "answer": "A", "options": ["might", "must", "can''t", "mustn''t"], "explanation": "might be 可能"}, {"q": "8", "answer": "B", "options": ["here", "gone", "new", "big"], "explanation": "不见了 gone"}, {"q": "9", "answer": "D", "options": ["seeing", "see", "seen", "saw"], "explanation": "看见 saw"}, {"q": "10", "answer": "B", "options": ["lost", "solved", "sold", "kept"], "explanation": "被解开 solved"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U8', 'Clues and Guesses', 'Good detectives are skilled at making (1)____. They look at clues and try to find the (2)____. For example, if a window is broken, someone (3)____ have come in that way. If there is mud on the floor, the person (4)____ have come from outside. A good detective never (5)____. He thinks about every (6)____. Sometimes a clue (7)____ point to one person, but the detective checks again to be (8)____. Making careful guesses helps to (9)____ a mystery. We can all learn from detectives. When we are not sure about something, we should look for (10)____ before we decide.', 100, 3, '[{"q": "1", "answer": "A", "options": ["guesses", "color", "game", "price"], "explanation": "猜测 guesses"}, {"q": "2", "answer": "D", "options": ["song", "price", "color", "truth"], "explanation": "真相 truth"}, {"q": "3", "answer": "A", "options": ["might", "can''t", "mustn''t", "must"], "explanation": "might have come 可能"}, {"q": "4", "answer": "C", "options": ["could", "might", "must", "can''t"], "explanation": "must have come 一定"}, {"q": "5", "answer": "B", "options": ["runs", "guesses", "wins", "sleeps"], "explanation": "从不瞎猜 never guesses"}, {"q": "6", "answer": "D", "options": ["price", "color", "game", "clue"], "explanation": "线索 clue"}, {"q": "7", "answer": "C", "options": ["can''t", "must", "might", "mustn''t"], "explanation": "might point 可能"}, {"q": "8", "answer": "A", "options": ["sure", "sleepy", "tired", "happy"], "explanation": "确定 sure"}, {"q": "9", "answer": "B", "options": ["break", "solve", "lose", "throw"], "explanation": "解开 solve"}, {"q": "10", "answer": "B", "options": ["prices", "clues", "games", "colors"], "explanation": "线索 clues"}]'::jsonb, 6);
