INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U8 听力·短文 The UFO Night', '九年级 Unit8 听力·神秘事件/情态动词推测', 2, 'One summer night, Jean saw a bright light in the sky.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U8 听力·对话 Whose Things', '九年级 Unit8 听力·神秘事件/情态动词推测', 2, 'W: There are some things left after the party. Whose are they?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U8 听力·短文 Making Guesses', '九年级 Unit8 听力·神秘事件/情态动词推测', 2, 'In daily life, we often make guesses with special words.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'A Mystery Story', '写一个关于谜团或奇怪事件的短文(如:夜里的怪声、捡到的失物、天空中的怪光)。用情态动词must/might/could/can''t表达你的推测。60词左右。', 'Write a short passage on the topic: "A Mystery Story".', '["发生了什么奇怪的事", "你的推测(用must/might/could/can''t)", "你如何寻找答案", "最后谜团是否解开"]'::jsonb, 70, 100, 'One night, my family heard a strange noise outside. "What could it be?" we asked. My brother thought it might be a cat, but it was too loud. It couldn''t be a small animal. "It must be something bigger," said my father. The next morning, we found our rubbish bins open. It must have been a large dog! At last, the mystery was solved, and we all felt relieved.', 'content:含奇怪事件/推测/寻找答案/结果(4分)；language:正确使用must/might/could/can''t推测(3分)；structure:叙事清楚、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'A Mystery Story', '["It must be ...", "It might / could be ...", "It can''t be ...", "Whose ... is this?", "belong to ...", "I wonder ...", "The mystery was solved."]'::jsonb, '[]'::jsonb, '要点:发生了什么奇怪的事；你的推测(用must/might/could/can''t)；你如何寻找答案；最后谜团是否解开', '9', 'U8' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U8' AND topic='A Mystery Story');
